// Same rules as src/pii.py, ported to JavaScript; tests/workflow.test.mjs runs both over shared samples.
const EMAIL = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi;
const CARD = /(?<!\d)(?:\d[ -]?){12,18}\d(?!\d)/g;
const PHONE = /(?<![\w])\+?\(?\d(?:[\s().-]*\d){7,17}(?![\w])/g;

function validCard(digits) {
  let total = 0;
  [...digits].reverse().forEach((character, index) => {
    let value = Number(character);
    if (index % 2) {
      value *= 2;
      if (value > 9) value -= 9;
    }
    total += value;
  });
  return total % 10 === 0;
}

function sanitizePii(text) {
  return text
    .replace(EMAIL, '[REDACTED_EMAIL]')
    .replace(CARD, (match) => (validCard(match.replace(/\D/g, '')) ? '[REDACTED_CARD]' : match))
    .replace(PHONE, (match) => {
      const digits = match.replace(/\D/g, '').length;
      const minimum = match.startsWith('+') ? 8 : 10;
      return minimum <= digits && digits <= 15 ? '[REDACTED_PHONE]' : match;
    });
}

const body = $input.first().json.body || {};
const field = (key) => (typeof body[key] === 'string' ? body[key].trim() : '');
const [ticketId, email, message, tier] = ['ticket_id', 'customer_email', 'message', 'tier'].map(field);

const errors = [];
if (!/^[A-Za-z0-9_-]{1,100}$/.test(ticketId)) errors.push('ticket_id must be 1-100 letters, digits, _ or -');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('customer_email must be a valid email');
if (!message || message.length > 20000) errors.push('message must be 1-20000 characters');
if (!tier || tier.length > 80) errors.push('tier must be 1-80 characters');
if (errors.length) {
  return [{ json: { status: 'invalid_request', ticket_id: ticketId || null, errors, http_status: 400 } }];
}

// Only masked text continues: the raw email and message stay in this node's input.
return [{ json: {
  status: 'validated',
  ticket_id: ticketId,
  tier,
  customer_email: '[REDACTED_EMAIL]',
  sanitized_message: sanitizePii(message),
} }];

// Idempotency key: ticket_id. State lives in n8n's workflow static data (its own database), so the demo
// needs no external store. Single instance only: production should claim the id in a DB with a unique constraint.
const TTL_MS = 7 * 24 * 60 * 60 * 1000;
const ticket = $input.first().json;
const state = $getWorkflowStaticData('global');
const now = Date.now();
const seen = state.seen_tickets || {};
for (const [id, seenAt] of Object.entries(seen)) {
  if (now - seenAt > TTL_MS) delete seen[id];
}
state.seen_tickets = seen;

if (seen[ticket.ticket_id]) {
  return [{ json: {
    status: 'duplicate',
    ticket_id: ticket.ticket_id,
    first_seen_at: new Date(seen[ticket.ticket_id]).toISOString(),
    http_status: 200,
  } }];
}

seen[ticket.ticket_id] = now;
return [{ json: ticket }];

// Fed by both outputs of Classify Ticket: the model reply, or { error } once n8n's retries gave up.
const reply = $input.first().json;
const ticket = $('Validate and Mask PII').first().json;
const review = (reason) => [{ json: { status: 'needs_review', ticket_id: ticket.ticket_id, reason, http_status: 202 } }];

if (reply.error) return review('model_unavailable');

let classification;
try {
  classification = JSON.parse(reply.choices?.[0]?.message?.content);
} catch {
  return review('invalid_classification');
}
const { severity, summary } = classification || {};
if (!['Low', 'Medium', 'High', 'Critical'].includes(severity) || typeof summary !== 'string' || !summary.trim()) {
  return review('invalid_classification');
}

return [{ json: { ...ticket, status: 'classified', severity, summary: summary.trim().slice(0, 160) } }];

// Stands in for the Asana node: builds the task payload and calls nothing.
const ticket = $input.first().json;
return [{ json: {
  ...ticket,
  asana_task: {
    name: `[${ticket.severity}] ${ticket.ticket_id}: ${ticket.summary}`,
    notes: ticket.sanitized_message,
    simulated: true,
  },
} }];

// Stands in for the Slack node: builds the on-call alert and calls nothing.
const ticket = $input.first().json;
return [{ json: {
  ...ticket,
  status: 'accepted',
  route: 'asana_slack',
  slack_alert: {
    text: `Critical Enterprise ticket ${ticket.ticket_id}: ${ticket.summary}`,
    simulated: true,
  },
  http_status: 202,
} }];

// Stands in for the HubSpot node: builds the ticket payload and calls nothing.
const ticket = $input.first().json;
return [{ json: {
  ...ticket,
  status: 'accepted',
  route: 'hubspot',
  hubspot_ticket: {
    subject: `[${ticket.severity}] ${ticket.ticket_id}: ${ticket.summary}`,
    content: ticket.sanitized_message,
    simulated: true,
  },
  http_status: 202,
} }];
